  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val RequestQualification_coordinationProcess_requestQualification_id = Arch.EITMonitoringAcquisitionCoordinatorSystem_Instance_coordinationProcess_requestQualification.id
    val AcquisitionEvidenceQualification_coordinationProcess_acquisitionEvidenceQualification_id = Arch.EITMonitoringAcquisitionCoordinatorSystem_Instance_coordinationProcess_acquisitionEvidenceQualification.id
