    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case RequestQualification_coordinationProcess_requestQualification_id =>
          val prefix = "RequestQualification_coordinationProcess_requestQualification_RM_TestSuite"
          val path = testRoot /+ ISZ("eit_acquisition_coordinator","EIT_Acquisition_Coordinator")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package eit_acquisition_coordinator.EIT_Acquisition_Coordinator
                |
                |import org.sireum._
                |import eit_acquisition_coordinator.EIT_Acquisition_Coordinator._
                |
                |class ${suiteName} extends RequestQualification_coordinationProcess_requestQualification_GumboX_TestHarness_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case AcquisitionEvidenceQualification_coordinationProcess_acquisitionEvidenceQualification_id =>
          val prefix = "AcquisitionEvidenceQualification_coordinationProcess_acquisitionEvidenceQualification_RM_TestSuite"
          val path = testRoot /+ ISZ("eit_acquisition_coordinator","EIT_Acquisition_Coordinator")
